/// Entry point for building prompts.
final class Prompts {
  final _Spec_Templates _spec;
  const Prompts._(this._spec);
}

// <static:dart-logic>
dynamic _evaluate(_Spec_Expression expression, dynamic val) {
  switch (expression) {
    case _Spec_Expression_KindInput():
      return val;
    case _Spec_Expression_KindProperty():
      final obj = _evaluate(expression.left, val);
      if (obj is Map) {
        return obj[expression.property];
      }
      return null;
  }
}

String _indent(String text, String spaces) {
  if (spaces.isEmpty) return text;
  return text.replaceAll('\n', '\n$spaces');
}

String _formatTable(dynamic v, _Spec_InsertFormat fmt) {
  if (v is! List || v.isEmpty) return '';
  final separator = fmt == _Spec_InsertFormat.csv ? ',' : '\t';
  final firstRow = v.first;
  if (firstRow is! Map) return '';
  final headers = firstRow.keys.map((k) => k.toString()).toList();
  final lines = <String>[headers.join(separator)];
  for (final item in v) {
    if (item is Map) {
      final cells = <String>[];
      for (final key in headers) {
        final cellVal = item[key];
        final str = cellVal?.toString() ?? '';
        if (fmt == _Spec_InsertFormat.csv) {
          if (str.contains('"') ||
              str.contains(',') ||
              str.contains('\n') ||
              str.contains('\r')) {
            cells.add('"${str.replaceAll('"', '""')}"');
          } else {
            cells.add(str);
          }
        } else {
          cells.add(
            str
                .replaceAll('\\', '\\\\')
                .replaceAll('\t', '\\t')
                .replaceAll('\n', '\\n')
                .replaceAll('\r', '\\r'),
          );
        }
      }
      lines.add(cells.join(separator));
    }
  }
  return lines.join('\n');
}

String _formatValue(dynamic v, _Spec_InsertFormat? fmt) {
  switch (fmt) {
    case null:
    case _Spec_InsertFormat.text:
      return v?.toString() ?? '';
    case _Spec_InsertFormat.json:
      return JsonEncoder.withIndent('  ').convert(v);
    case _Spec_InsertFormat.yaml:
      return YamlWriter().write(v).trimRight();
    case _Spec_InsertFormat.toon:
      return v == null ? 'null' : toon.encode(v);
    case _Spec_InsertFormat.csv:
    case _Spec_InsertFormat.tsv:
      return _formatTable(v, fmt);
  }
}

String _renderBody(
  List<_Spec_BodyPiece>? body,
  dynamic inp,
  Map<String, _Spec_Snippet> snippets,
) {
  if (body == null || body.isEmpty) return '';
  final sb = StringBuffer();
  for (final piece in body) {
    switch (piece) {
      case _Spec_BodyPiece_KindText():
        sb.write(piece.text);
      case _Spec_BodyPiece_KindInsertVal():
        final val = _evaluate(piece.val, inp);
        final formatted = _formatValue(val, piece.format);
        sb.write(_indent(formatted, piece.indent));
      case _Spec_BodyPiece_KindInsertSnippet():
        final snippet = snippets[piece.snippet];
        if (snippet == null) {
          throw ArgumentError('Snippet not found: ${piece.snippet}');
        }
        final renderedSnippet = _renderSnippet(snippet, inp, snippets);
        sb.write(_indent(renderedSnippet, piece.indent));
    }
  }
  return sb.toString();
}

String _renderSnippet(
  _Spec_Snippet snippet,
  dynamic inp,
  Map<String, _Spec_Snippet> snippets,
) {
  switch (snippet) {
    case _Spec_Snippet_KindSnippet():
      return _renderBody(snippet.body, inp, snippets);
    case _Spec_Snippet_KindSnippetIf():
      final evalResult = _evaluate(snippet.expression, inp);
      bool condition;
      switch (snippet.is_) {
        case _Spec_Snippet_KindSnippetIf_Is.notEmpty:
          if (evalResult is Iterable) {
            condition = evalResult.isNotEmpty;
          } else if (evalResult is Map) {
            condition = evalResult.isNotEmpty;
          } else if (evalResult is String) {
            condition = evalResult.isNotEmpty;
          } else {
            condition = evalResult != null;
          }
        case _Spec_Snippet_KindSnippetIf_Is.notNull:
          condition = evalResult != null;
        case _Spec_Snippet_KindSnippetIf_Is.true_:
          if (evalResult is bool) {
            condition = evalResult;
          } else if (evalResult is String) {
            condition = evalResult.isNotEmpty;
          } else if (evalResult is num) {
            condition = evalResult != 0;
          } else {
            condition = evalResult != null;
          }
      }
      return _renderBody(
          condition ? snippet.then : snippet.else_, inp, snippets);
    case _Spec_Snippet_KindSnippetSwitch():
      final switchVal = _evaluate(snippet.expression, inp);
      final switchKey = switchVal is bool
          ? (switchVal ? 'true' : 'false')
          : (switchVal?.toString() ?? '');
      final branch = snippet.branches[switchKey];
      if (branch == null) {
        throw ArgumentError('Branch not found: $switchKey');
      }
      return _renderBody(branch, inp, snippets);
  }
}

List<FewShotExample> _renderExamples(
  List<_Spec_FewShotExample>? examples,
  List<_Spec_BodyPiece>? userBody,
  _Spec_Template tmpl,
) {
  if (examples == null || examples.isEmpty) return const [];
  final result = <FewShotExample>[];
  for (final ex in examples) {
    final exInputObj = _inputToObject(ex.input);
    final exOutputObj = _inputToObject(ex.output);
    final userMessage = _renderBody(userBody, exInputObj, tmpl.snippets);

    final intermediateSteps = <IntermediateStepExample>[];
    for (final step in ex.intermediateSteps) {
      final toolCalls = <ToolCallExample>[];
      for (final tc in step.toolCalls) {
        toolCalls.add(
          ToolCallExample(
            callId: tc.callId,
            toolName: tc.toolName,
            stringifiedInput: jsonEncode(tc.input),
            stringifiedOutput: jsonEncode(tc.output),
          ),
        );
      }
      intermediateSteps.add(IntermediateStepExample(toolCalls: toolCalls));
    }

    final outputFormat = tmpl.outputFormat == _Spec_OutputFormat.json
        ? _Spec_InsertFormat.json
        : _Spec_InsertFormat.text;
    final response = _formatValue(exOutputObj, outputFormat);

    result.add(
      FewShotExample(
        userMessage: userMessage,
        intermediateSteps: intermediateSteps,
        response: response,
      ),
    );
  }
  return result;
}

dynamic _inputToObject(dynamic input) {
  if (input == null) return null;
  if (input is num || input is bool || input is String) return input;
  if (input is List) return input.map(_inputToObject).toList();
  if (input is Map) {
    return input.map((k, v) => MapEntry(k.toString(), _inputToObject(v)));
  }
  try {
    final json = (input as dynamic).toJson();
    return _inputToObject(json);
  } catch (_) {
    return input.toString();
  }
}

TemplateId _parseTemplateId(String id) {
  for (final t in TemplateId.values) {
    if (t.toString() == id) return t;
  }
  return TemplateId.values.first;
}

Prompt<Output, ToolExecutor> _doRender<Output, ToolExecutor>(
  _Spec_Templates spec,
  String templateId,
  dynamic rawInput, {
  Output Function(dynamic json)? fromJson,
}) {
  final template = spec.templates[templateId];
  if (template == null) {
    throw ArgumentError('Template not found: $templateId');
  }

  final inputObj = _inputToObject(rawInput);
  final snippets = template.snippets;
  final contents = template.contents;

  dynamic metaElement;
  String systemMessage;
  String userMessage;
  List<FewShotExample> examples;

  switch (contents) {
    case _Spec_TemplateContents_KindNoVariants():
      final content = contents.content;
      metaElement = content.meta;
      systemMessage = _renderBody(content.system, inputObj, snippets);
      final userBody = content.user ?? const [];
      userMessage = _renderBody(userBody, inputObj, snippets);
      examples = _renderExamples(content.examples, userBody, template);
    case _Spec_TemplateContents_KindVariants():
      if (inputObj is! Map) {
        throw ArgumentError('Input for template with variants must be a map');
      }
      final variant = inputObj['variant']?.toString();
      if (variant == null) {
        throw ArgumentError("Missing 'variant' field in input");
      }
      final variantContent = contents.variants[variant];
      if (variantContent == null) {
        throw ArgumentError('Unknown variant: $variant');
      }
      final defaultContent = contents.defaultContent;

      metaElement = variantContent.meta ?? defaultContent.meta;
      final systemBody =
          variantContent.system ?? defaultContent.system ?? const [];
      final userBody = variantContent.user ?? defaultContent.user ?? const [];
      systemMessage = _renderBody(systemBody, inputObj, snippets);
      userMessage = _renderBody(userBody, inputObj, snippets);
      final rawExamples = variantContent.examples ?? defaultContent.examples;
      examples = _renderExamples(rawExamples, userBody, template);
  }

  final tools = <String, Tool>{};
  for (final templateTool in template.tools) {
    final specTool = spec.tools[templateTool.id];
    if (specTool != null) {
      tools[templateTool.name] = Tool(
        name: templateTool.name,
        description: specTool.description,
      );
    }
  }

  final OutputFormat outputFormat;
  if (template.outputFormat == _Spec_OutputFormat.json) {
    outputFormat = JsonOutputFormat._(
      stringifiedJsonSchema: jsonEncode(template.outputJsonSchema),
      fromJson: fromJson!,
    );
  } else {
    outputFormat = const TextOutputFormat();
  }

  return Prompt<Output, ToolExecutor>(
    meta: _parseMeta(metaElement),
    systemMessage: systemMessage,
    userMessage: userMessage,
    examples: examples,
    tools: tools,
    outputFormat: outputFormat,
    templateId: _parseTemplateId(templateId),
  );
}

Output _doParseResponse<Output>(
  String response,
  OutputFormat outputFormat,
  TemplateId templateId,
) {
  switch (outputFormat) {
    case JsonOutputFormat():
      var cleaned = response.trim();
      if (cleaned.startsWith('```')) {
        if (cleaned.startsWith('```json')) {
          cleaned = cleaned.substring('```json'.length);
        } else {
          cleaned = cleaned.substring('```'.length);
        }
        if (cleaned.endsWith('```')) {
          cleaned = cleaned.substring(0, cleaned.length - '```'.length);
        }
        cleaned = cleaned.trim();
      }
      try {
        final decoded = jsonDecode(cleaned);
        return outputFormat._fromJson(decoded) as Output;
      } catch (e) {
        throw FormatException("Template '$templateId': $e");
      }
    case TextOutputFormat():
      return response as Output;
  }
}

/// Use this with external frameworks that support template override injection
/// for experimentation or A/B testing.
///
/// When using overrides, inject the resulting [Prompts] instance as a
/// dependency rather than relying on the global [prompts] variable.
abstract final class TemplateOverrider {
  static Map<String, dynamic> templatesData() {
    return _templatesData.toJson();
  }

  static Prompts applyOverrides(Map<String, dynamic> overrides) {
    final sig = overrides['signature'] as String?;
    if (sig != _templatesData.signature) {
      throw ArgumentError('Signature mismatch');
    }
    final mergedTemplates =
        Map<String, _Spec_Template>.from(_templatesData.templates);
    if (overrides['templates'] is Map) {
      final overrideTemplates = (overrides['templates'] as Map).map(
        (k, v) => MapEntry(
            k.toString(), _Spec_Template.fromJson(v as Map<String, dynamic>)),
      );
      mergedTemplates.addAll(overrideTemplates);
    }
    final mergedTools = Map<String, _Spec_Tool>.from(_templatesData.tools);
    if (overrides['tools'] is Map) {
      final overrideTools = (overrides['tools'] as Map).map(
        (k, v) => MapEntry(
            k.toString(), _Spec_Tool.fromJson(v as Map<String, dynamic>)),
      );
      mergedTools.addAll(overrideTools);
    }
    final mergedData = _Spec_Templates(
      edition: _templatesData.edition,
      signature: _templatesData.signature,
      templates: mergedTemplates,
      tools: mergedTools,
      singleNamespace: _templatesData.singleNamespace,
      sourceFiles: _templatesData.sourceFiles,
    );
    return Prompts._(mergedData);
  }
}

/// Entry point for building prompts.
final prompts = Prompts._(_templatesData);
// </static:dart-logic>
